  3	import com.pousada.marealta.api.ApiResponse;
  4	import com.pousada.marealta.db.Database;
  5	import com.pousada.marealta.models.*;
  6	import com.pousada.marealta.services.EmailService;
  7	import com.pousada.marealta.services.ReservationService;
  8	import com.pousada.marealta.util.PricingUtil;
  9	import io.javalin.Javalin;
 10	import io.javalin.http.Context;
 11	
 12	import java.math.BigDecimal;
 13	import java.sql.SQLException;
 14	import java.time.LocalDate;
 15	import java.time.YearMonth;
 16	import java.time.format.DateTimeFormatter;
 17	import java.util.List;
 18	import java.util.Map;
 19	
 20	public class Main {
 21	    private static Database database;
 22	    private static ReservationService reservationService;
 23	    private static EmailService emailService;
 24	
 25	    public static void main(String[] args) throws SQLException {
 26	        String dbUrl = System.getenv("DB_URL");
 27	        String dbUser = System.getenv("DB_USER");
 28	        String dbPassword = System.getenv("DB_PASSWORD");
 29	        String portStr = System.getenv("PORT");
 30	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 31	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 32	
 33	        database = new Database(dbUrl, dbUser, dbPassword);
 34	        database.initialize();
 35	
 36	        emailService = new EmailService(database, testMode);
 37	        reservationService = new ReservationService(database, emailService);
 38	
 39	        Javalin app = Javalin.create().start(port);
 40	
 41	        app.get("/rooms", Main::getRooms);
 42	        app.post("/reservations", Main::createReservation);
 43	        app.get("/reservations/{id}", Main::getReservation);
 44	        app.post("/reservations/{id}/confirmation", Main::confirmReservation);
 45	        app.post("/reservations/{id}/cancellation", Main::cancelReservation);
 46	        app.post("/reservations/{id}/check-in", Main::checkIn);
 47	        app.post("/reservations/{id}/check-out", Main::checkOut);
 48	        app.get("/reservations/{id}/document", Main::getDocument);
 49	        app.get("/messages", Main::getMessages);
 50	        app.get("/reports/occupancy", Main::getOccupancyReport);
 51	        app.get("/reports/revenue", Main::getRevenueReport);
 52	
 53	        app.exception(Exception.class, (e, ctx) -> {
 54	            e.printStackTrace();
 55	            ctx.status(500);
 56	            ctx.json(new ApiResponse("INTERNAL_ERROR", e.getMessage()));
 57	        });
 58	    }
 59	
 60	    private static void getRooms(Context ctx) throws SQLException {
 61	        List<Room> rooms = database.getAllRooms();
 62	        ctx.json(rooms);
 63	    }
 64	
 65	    private static void createReservation(Context ctx) throws SQLException {
 66	        try {
 67	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
 68	
 69	            int roomNumber = ((Number) body.get("roomNumber")).intValue();
 70	            String guestName = (String) body.get("guestName");
 71	            String guestEmail = (String) body.get("guestEmail");
 72	            String guestCpf = (String) body.get("guestCpf");
 73	            String checkInStr = (String) body.get("checkIn");
 74	            String checkOutStr = (String) body.get("checkOut");
 75	            int guests = ((Number) body.get("guests")).intValue();
 76	            String ratePlan = (String) body.get("ratePlan");
 77	
 78	            LocalDate checkIn = LocalDate.parse(checkInStr);
 79	            LocalDate checkOut = LocalDate.parse(checkOutStr);
 80	
 81	            Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail, guestCpf,
 82	                    checkIn, checkOut, guests, ratePlan);
 83	
 84	            ctx.status(201);
 85	            ctx.json(reservation);
 86	        } catch (IllegalArgumentException e) {
 87	            handleError(ctx, e.getMessage());
 88	        } catch (Exception e) {
 89	            ctx.status(400);
 90	            ctx.json(new ApiResponse("INVALID_REQUEST", e.getMessage()));
 91	        }
 92	    }
 93	
 94	    private static void getReservation(Context ctx) throws SQLException {
 95	        try {
 96	            long id = Long.parseLong(ctx.pathParam("id"));
 97	            Reservation reservation = database.getReservation(id);
 98	            if (reservation == null) {
 99	                ctx.status(404);
100	                ctx.json(new ApiResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
101	            } else {
102	                ctx.json(reservation);
103	            }
104	        } catch (NumberFormatException e) {
105	            ctx.status(400);
106	            ctx.json(new ApiResponse("INVALID_REQUEST", "Invalid reservation ID"));
107	        }
108	    }
109	
110	    private static void confirmReservation(Context ctx) throws SQLException {
111	        try {
112	            long id = Long.parseLong(ctx.pathParam("id"));
113	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
114	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
115	
116	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
117	            ctx.json(reservation);
118	        } catch (IllegalArgumentException e) {
119	            handleError(ctx, e.getMessage());
120	        } catch (Exception e) {
121	            ctx.status(400);
122	            ctx.json(new ApiResponse("INVALID_REQUEST", e.getMessage()));
123	        }
124	    }
125	
126	    private static void cancelReservation(Context ctx) throws SQLException {
127	        try {
128	            long id = Long.parseLong(ctx.pathParam("id"));
129	            Reservation reservation = reservationService.cancelReservation(id);
130	            ctx.json(reservation);
131	        } catch (IllegalArgumentException e) {
132	            handleError(ctx, e.getMessage());
133	        } catch (Exception e) {
134	            ctx.status(400);
135	            ctx.json(new ApiResponse("INVALID_REQUEST", e.getMessage()));
136	        }
137	    }
138	
139	    private static void checkIn(Context ctx) throws SQLException {
140	        try {
141	            long id = Long.parseLong(ctx.pathParam("id"));
142	            Reservation reservation = reservationService.checkIn(id);
143	            ctx.json(reservation);
144	        } catch (IllegalArgumentException e) {
