151	
152	    private static void checkOut(Context ctx) throws SQLException {
153	        try {
154	            long id = Long.parseLong(ctx.pathParam("id"));
155	            Receipt receipt = reservationService.checkOut(id);
156	            ctx.json(receipt);
157	        } catch (IllegalArgumentException e) {
