164	
165	    private static void getDocument(Context ctx) throws SQLException {
166	        try {
167	            long id = Long.parseLong(ctx.pathParam("id"));
168	            Receipt receipt = reservationService.getReceipt(id);
169	            ctx.json(receipt);
170	        } catch (IllegalArgumentException e) {
171	            handleError(ctx, e.getMessage());
