177	
178	    private static void getMessages(Context ctx) throws SQLException {
179	        List<Message> messages = database.getAllMessages();
180	        ctx.json(messages);
181	    }
182	
183	    private static void getOccupancyReport(Context ctx) throws SQLException {
184	        try {
185	            String dateStr = ctx.queryParam("date");
186	            if (dateStr == null || dateStr.isEmpty()) {
187	                ctx.status(400);
188	                ctx.json(new ApiResponse("INVALID_REQUEST", "date parameter required"));
189	                return;
190	            }
191	
192	            LocalDate date = LocalDate.parse(dateStr);
193	            List<String[]> report = database.getOccupancyReport(date);
194	
195	            StringBuilder csv = new StringBuilder();
196	            csv.append("room,type,reservation,check_in,check_out\n");
197	            for (String[] row : report) {
198	                csv.append(String.join(",", row)).append("\n");
199	            }
200	
201	            ctx.contentType("text/csv; charset=utf-8");
202	            ctx.result(csv.toString());
203	        } catch (Exception e) {
204	            ctx.status(400);
205	            ctx.json(new ApiResponse("INVALID_REQUEST", e.getMessage()));
206	        }
207	    }
208	
209	    private static void getRevenueReport(Context ctx) throws SQLException {
210	        try {
211	            String monthStr = ctx.queryParam("month");
212	            if (monthStr == null || monthStr.isEmpty()) {
213	                ctx.status(400);
214	                ctx.json(new ApiResponse("INVALID_REQUEST", "month parameter required"));
215	                return;
216	            }
217	
218	            YearMonth yearMonth = YearMonth.parse(monthStr);
219	            List<String[]> report = database.getRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
220	
221	            StringBuilder csv = new StringBuilder();
222	            csv.append("reservation,room,check_in,check_out,status,amount\n");
223	            for (String[] row : report) {
224	                csv.append(String.join(",", row)).append("\n");
225	            }
226	
227	            ctx.contentType("text/csv; charset=utf-8");
228	            ctx.result(csv.toString());
229	        } catch (Exception e) {
230	            ctx.status(400);
231	            ctx.json(new ApiResponse("INVALID_REQUEST", e.getMessage()));
232	        }
233	    }
234	
235	    private static void handleError(Context ctx, String errorCode) {
236	        switch (errorCode) {
237	            case "ROOM_NOT_FOUND":
238	                ctx.status(404);
239	                ctx.json(new ApiResponse("ROOM_NOT_FOUND", "Room not found"));
240	                break;
241	            case "RESERVATION_NOT_FOUND":
242	                ctx.status(404);
243	                ctx.json(new ApiResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
244	                break;
245	            case "ROOM_UNAVAILABLE":
246	                ctx.status(409);
247	                ctx.json(new ApiResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
248	                break;
249	            case "CAPACITY_EXCEEDED":
250	                ctx.status(422);
251	                ctx.json(new ApiResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
252	                break;
253	            case "OPERATION_NOT_ALLOWED":
254	                ctx.status(409);
255	                ctx.json(new ApiResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation status"));
256	                break;
257	            case "INVALID_REQUEST":
258	                ctx.status(400);
259	                ctx.json(new ApiResponse("INVALID_REQUEST", "Invalid request"));
260	                break;
261	            default:
262	                ctx.status(400);
263	                ctx.json(new ApiResponse("INVALID_REQUEST", "Invalid request"));
264	        }
265	    }
266	}
