273	
274	import java.sql.SQLException;
275	
276	public class EmailService {
277	    private static final String ARCHIVE_EMAIL = "arquivo@pousadamarealta.com.br";
278	    private static final String TEST_EMAIL = "testes@pousadamarealta.com.br";
279	    private static final String ARCHIVE_PREFIX = "[Cópia] ";
280	    private static final String TEST_PREFIX = "[TESTE] ";
281	
282	    private final Database database;
283	    private final boolean testMode;
284	
285	    public EmailService(Database database, boolean testMode) {
286	        this.database = database;
287	        this.testMode = testMode;
288	    }
289	
290	    public void sendConfirmationEmail(String guestName, String guestEmail, String receiptText) throws SQLException {
291	        String subject = "Reserva confirmada - Pousada Maré Alta";
292	        String body = buildConfirmationBody(guestName, receiptText);
293	
294	        sendEmail(guestEmail, subject, body);
295	    }
296	
297	    public void sendEmail(String toEmail, String subject, String body) throws SQLException {
298	        boolean isValidEmail = EmailValidator.isValid(toEmail);
299	
300	        if (!isValidEmail) {
301	            database.createMessage("EMAIL", toEmail, subject, body, MessageStatus.BLOCKED);
302	            return;
303	        }
304	
305	        String finalEmail = toEmail;
306	        String finalSubject = subject;
307	        String finalBody = body;
308	
309	        if (testMode) {
310	            finalEmail = TEST_EMAIL;
311	            finalSubject = TEST_PREFIX + subject;
312	            finalBody = "Destinatário original: " + toEmail + "\n" + body;
313	        }
314	
315	        database.createMessage("EMAIL", finalEmail, finalSubject, finalBody, MessageStatus.SENT);
316	
317	        if (!testMode) {
318	            String archiveBody = body;
319	            String archiveSubject = ARCHIVE_PREFIX + subject;
320	            database.createMessage("EMAIL", ARCHIVE_EMAIL, archiveSubject, archiveBody, MessageStatus.SENT);
321	        }
322	    }
323	
324	    private String buildConfirmationBody(String guestName, String receiptText) {
325	        return "Olá, " + guestName + "!\n\n" +
326	               "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
327	               receiptText + "\n\n" +
328	               "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
329	               "Até breve!";
330	    }
331	}
332	package com.pousada.marealta.services;
333	
334	import com.pousada.marealta.db.Database;
335	import com.pousada.marealta.models.Receipt;
336	import com.pousada.marealta.models.Reservation;
337	import com.pousada.marealta.models.ReservationStatus;
338	import com.pousada.marealta.models.Room;
339	import com.pousada.marealta.util.PricingUtil;
340	import com.pousada.marealta.util.ReceiptFormatter;
341	
342	import java.math.BigDecimal;
343	import java.sql.SQLException;
344	import java.time.LocalDate;
345	
346	public class ReservationService {
347	    private final Database database;
348	    private final EmailService emailService;
349	
350	    public ReservationService(Database database, EmailService emailService) {
351	        this.database = database;
352	        this.emailService = emailService;
353	    }
354	
355	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
356	                                         LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan) throws SQLException {
357	        Room room = database.getRoom(roomNumber);
358	        if (room == null) {
359	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
360	        }
361	
362	        if (guests < 1) {
363	            throw new IllegalArgumentException("INVALID_REQUEST");
364	        }
365	
366	        if (guests > room.capacity) {
367	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
368	        }
369	
370	        if (!checkOut.isAfter(checkIn)) {
371	            throw new IllegalArgumentException("INVALID_REQUEST");
372	        }
373	
374	        if (!database.isRoomAvailable(roomNumber, checkIn, checkOut, -1)) {
375	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
376	        }
377	
378	        int nights = PricingUtil.countNights(checkIn, checkOut);
379	        BigDecimal subtotal = PricingUtil.calculateSubtotal(room.nightlyRate, checkIn, checkOut);
380	        BigDecimal discount = PricingUtil.calculateDiscount(subtotal, ratePlan);
381	        BigDecimal total = PricingUtil.calculateTotal(subtotal, discount);
382	
383	        long reservationId = database.createReservation(roomNumber, guestName, guestEmail, guestCpf,
384	                checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
385	
386	        return database.getReservation(reservationId);
387	    }
388	
389	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws SQLException {
390	        Reservation res = database.getReservation(reservationId);
391	        if (res == null) {
392	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
393	        }
394	
395	        if (res.status != ReservationStatus.PENDING) {
396	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
397	        }
398	
399	        database.updateReservationStatus(reservationId, ReservationStatus.CONFIRMED, amountPaid, null);
400	        Reservation confirmed = database.getReservation(reservationId);
401	
402	        Room room = database.getRoom(res.roomNumber);
403	        Receipt receipt = new Receipt(reservationId, res.guestName, res.guestCpf, res.roomNumber,
404	                room.type, res.checkIn, res.checkOut, res.nights, res.subtotal, res.discount, res.total);
405	        String receiptText = ReceiptFormatter.format(receipt);
406	
407	        emailService.sendConfirmationEmail(res.guestName, res.guestEmail, receiptText);
408	
409	        return confirmed;
410	    }
411	
412	    public Reservation checkIn(long reservationId) throws SQLException {
413	        Reservation res = database.getReservation(reservationId);
414	        if (res == null) {
415	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
416	        }
417	
418	        if (res.status != ReservationStatus.CONFIRMED) {
419	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
420	        }
421	
422	        database.updateReservationStatus(reservationId, ReservationStatus.CHECKED_IN, res.amountPaid, res.refund);
423	        return database.getReservation(reservationId);
424	    }
425	
426	    public Receipt checkOut(long reservationId) throws SQLException {
427	        Reservation res = database.getReservation(reservationId);
428	        if (res == null) {
429	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
430	        }
431	
432	        if (res.status != ReservationStatus.CHECKED_IN) {
433	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
434	        }
435	
436	        database.updateReservationStatus(reservationId, ReservationStatus.CHECKED_OUT, res.amountPaid, res.refund);
437	        Reservation updated = database.getReservation(reservationId);
438	
439	        Room room = database.getRoom(res.roomNumber);
440	        return new Receipt(reservationId, res.guestName, res.guestCpf, res.roomNumber,
441	                room.type, res.checkIn, res.checkOut, res.nights, res.subtotal, res.discount, res.total);
442	    }
443	
444	    public Reservation cancelReservation(long reservationId) throws SQLException {
445	        Reservation res = database.getReservation(reservationId);
446	        if (res == null) {
447	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
448	        }
449	
450	        if (res.status != ReservationStatus.PENDING && res.status != ReservationStatus.CONFIRMED) {
451	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
452	        }
453	
454	        BigDecimal refund = BigDecimal.ZERO;
455	        if (res.status == ReservationStatus.CONFIRMED) {
456	            if ("STANDARD".equals(res.ratePlan)) {
457	                refund = res.amountPaid;
458	            }
459	        }
460	
461	        database.updateReservationStatus(reservationId, ReservationStatus.CANCELLED, res.amountPaid, refund);
462	        return database.getReservation(reservationId);
463	    }
464	
465	    public Receipt getReceipt(long reservationId) throws SQLException {
466	        Reservation res = database.getReservation(reservationId);
467	        if (res == null) {
468	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
469	        }
470	
471	        if (res.status != ReservationStatus.CONFIRMED && res.status != ReservationStatus.CHECKED_IN && res.status != ReservationStatus.CHECKED_OUT) {
472	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
473	        }
474	
475	        Room room = database.getRoom(res.roomNumber);
476	        return new Receipt(reservationId, res.guestName, res.guestCpf, res.roomNumber,
477	                room.type, res.checkIn, res.checkOut, res.nights, res.subtotal, res.discount, res.total);
478	    }
479	}

