 10	public class Database {
 11	    private final String dbUrl;
 12	    private final String dbUser;
 13	    private final String dbPassword;
 14	
 15	    public Database(String dbUrl, String dbUser, String dbPassword) {
 16	        this.dbUrl = dbUrl;
 17	        this.dbUser = dbUser;
 18	        this.dbPassword = dbPassword;
 19	    }
 20	
 21	    public void initialize() throws SQLException {
 22	        try (Connection conn = getConnection()) {
 23	            createTables(conn);
 24	            initializeRooms(conn);
 25	        }
 26	    }
