 28	    private void createTables(Connection conn) throws SQLException {
 29	        try (Statement stmt = conn.createStatement()) {
 30	            stmt.execute("""
 31	                CREATE TABLE IF NOT EXISTS rooms (
 32	                    number INTEGER PRIMARY KEY,
 33	                    type VARCHAR(50) NOT NULL,
 34	                    capacity INTEGER NOT NULL,
 35	                    nightly_rate DECIMAL(10, 2) NOT NULL
 36	                )
 37	                """);
 38	
 39	            stmt.execute("""
 40	                CREATE TABLE IF NOT EXISTS reservations (
 41	                    id BIGSERIAL PRIMARY KEY,
 42	                    room_number INTEGER NOT NULL REFERENCES rooms(number),
 43	                    guest_name VARCHAR(255) NOT NULL,
 44	                    guest_email VARCHAR(255) NOT NULL,
 45	                    guest_cpf VARCHAR(14) NOT NULL,
 46	                    check_in DATE NOT NULL,
 47	                    check_out DATE NOT NULL,
 48	                    guests INTEGER NOT NULL,
 49	                    rate_plan VARCHAR(50) NOT NULL,
 50	                    nights INTEGER NOT NULL,
 51	                    subtotal DECIMAL(10, 2) NOT NULL,
 52	                    discount DECIMAL(10, 2) NOT NULL,
 53	                    total DECIMAL(10, 2) NOT NULL,
 54	                    status VARCHAR(50) NOT NULL,
 55	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
 56	                    refund DECIMAL(10, 2)
 57	                )
 58	                """);
 59	
 60	            stmt.execute("""
 61	                CREATE TABLE IF NOT EXISTS messages (
 62	                    id BIGSERIAL PRIMARY KEY,
 63	                    channel VARCHAR(50) NOT NULL,
 64	                    to_address VARCHAR(255) NOT NULL,
 65	                    subject VARCHAR(255) NOT NULL,
 66	                    body TEXT NOT NULL,
 67	                    status VARCHAR(50) NOT NULL
 68	                )
 69	                """);
 70	        }
 71	    }
 72	
 73	    private void initializeRooms(Connection conn) throws SQLException {
 74	        try (PreparedStatement pstmt = conn.prepareStatement(
 75	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?, ?, ?, ?) ON CONFLICT DO NOTHING")) {
 76	
 77	            Room[] rooms = {
 78	                new Room(101, "STANDARD", 2, new BigDecimal("249.90")),
 79	                new Room(102, "STANDARD", 2, new BigDecimal("249.90")),
 80	                new Room(201, "DELUXE", 3, new BigDecimal("389.90")),
 81	                new Room(202, "DELUXE", 3, new BigDecimal("389.90")),
 82	                new Room(301, "SUITE", 4, new BigDecimal("579.90"))
 83	            };
 84	
 85	            for (Room room : rooms) {
 86	                pstmt.setInt(1, room.number);
 87	                pstmt.setString(2, room.type);
 88	                pstmt.setInt(3, room.capacity);
 89	                pstmt.setBigDecimal(4, room.nightlyRate);
 90	                pstmt.addBatch();
 91	            }
 92	            pstmt.executeBatch();
 93	        }
 94	    }
 95	
 96	    public Connection getConnection() throws SQLException {
 97	        return DriverManager.getConnection(dbUrl, dbUser, dbPassword);
 98	    }
 99	
100	    public Room getRoom(int roomNumber) throws SQLException {
101	        try (Connection conn = getConnection();
102	             PreparedStatement pstmt = conn.prepareStatement(
103	                     "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?")) {
104	            pstmt.setInt(1, roomNumber);
105	            try (ResultSet rs = pstmt.executeQuery()) {
106	                if (rs.next()) {
107	                    return new Room(rs.getInt("number"), rs.getString("type"),
108	                            rs.getInt("capacity"), rs.getBigDecimal("nightly_rate"));
109	                }
110	            }
111	        }
112	        return null;
113	    }
114	
115	    public List<Room> getAllRooms() throws SQLException {
116	        List<Room> rooms = new ArrayList<>();
117	        try (Connection conn = getConnection();
118	             Statement stmt = conn.createStatement();
119	             ResultSet rs = stmt.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
120	            while (rs.next()) {
121	                rooms.add(new Room(rs.getInt("number"), rs.getString("type"),
122	                        rs.getInt("capacity"), rs.getBigDecimal("nightly_rate")));
123	            }
124	        }
125	        return rooms;
126	    }
127	
128	    public long createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
129	                                   LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan,
130	                                   int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) throws SQLException {
131	        try (Connection conn = getConnection();
132	             PreparedStatement pstmt = conn.prepareStatement(
133	                     "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id",
134	                     Statement.RETURN_GENERATED_KEYS)) {
135	            pstmt.setInt(1, roomNumber);
136	            pstmt.setString(2, guestName);
137	            pstmt.setString(3, guestEmail);
138	            pstmt.setString(4, guestCpf);
139	            pstmt.setDate(5, Date.valueOf(checkIn));
140	            pstmt.setDate(6, Date.valueOf(checkOut));
141	            pstmt.setInt(7, guests);
142	            pstmt.setString(8, ratePlan);
143	            pstmt.setInt(9, nights);
144	            pstmt.setBigDecimal(10, subtotal);
145	            pstmt.setBigDecimal(11, discount);
146	            pstmt.setBigDecimal(12, total);
147	            pstmt.setString(13, "PENDING");
148	            pstmt.setBigDecimal(14, BigDecimal.ZERO);
149	
150	            pstmt.executeUpdate();
151	            try (ResultSet rs = pstmt.getGeneratedKeys()) {
152	                if (rs.next()) {
153	                    return rs.getLong(1);
154	                }
155	            }
156	        }
157	        return -1;
158	    }
