160	    public Reservation getReservation(long id) throws SQLException {
161	        try (Connection conn = getConnection();
162	             PreparedStatement pstmt = conn.prepareStatement(
163	                     "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund FROM reservations WHERE id = ?")) {
164	            pstmt.setLong(1, id);
165	            try (ResultSet rs = pstmt.executeQuery()) {
166	                if (rs.next()) {
167	                    return mapReservation(rs);
168	                }
169	            }
170	        }
171	        return null;
