174	    public void updateReservationStatus(long id, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) throws SQLException {
175	        try (Connection conn = getConnection();
176	             PreparedStatement pstmt = conn.prepareStatement(
177	                     "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
178	            pstmt.setString(1, status.name());
179	            pstmt.setBigDecimal(2, amountPaid);
180	            pstmt.setBigDecimal(3, refund);
181	            pstmt.setLong(4, id);
182	            pstmt.executeUpdate();
