186	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, long excludeReservationId) throws SQLException {
187	        try (Connection conn = getConnection();
188	             PreparedStatement pstmt = conn.prepareStatement(
189	                     "SELECT COUNT(*) FROM reservations WHERE room_number = ? AND status != 'CANCELLED' AND id != ? AND check_in < ? AND check_out > ?")) {
190	            pstmt.setInt(1, roomNumber);
191	            pstmt.setLong(2, excludeReservationId);
192	            pstmt.setDate(3, Date.valueOf(checkOut));
193	            pstmt.setDate(4, Date.valueOf(checkIn));
194	            try (ResultSet rs = pstmt.executeQuery()) {
195	                if (rs.next()) {
196	                    return rs.getInt(1) == 0;
197	                }
198	            }
199	        }
200	        return true;
201	    }
202	
203	    public long createMessage(String channel, String to, String subject, String body, MessageStatus status) throws SQLException {
204	        try (Connection conn = getConnection();
205	             PreparedStatement pstmt = conn.prepareStatement(
206	                     "INSERT INTO messages (channel, to_address, subject, body, status) VALUES (?, ?, ?, ?, ?) RETURNING id",
207	                     Statement.RETURN_GENERATED_KEYS)) {
208	            pstmt.setString(1, channel);
209	            pstmt.setString(2, to);
210	            pstmt.setString(3, subject);
211	            pstmt.setString(4, body);
