345	public class EmailValidator {
346	    public static boolean isValid(String email) {
347	        if (email == null || email.trim().isEmpty()) {
348	            return false;
349	        }
350	
351	        int atCount = 0;
352	        int atIndex = -1;
353	        for (int i = 0; i < email.length(); i++) {
354	            if (email.charAt(i) == '@') {
355	                atCount++;
356	                atIndex = i;
357	            }
358	        }
359	
360	        if (atCount != 1) {
361	            return false;
362	        }
363	
364	        String local = email.substring(0, atIndex);
365	        String domain = email.substring(atIndex + 1);
366	
367	        if (local.isEmpty() || domain.isEmpty()) {
368	            return false;
369	        }
370	
371	        int dotCount = 0;
372	        for (char c : domain.toCharArray()) {
373	            if (c == '.') {
374	                dotCount++;
375	            }
376	        }
377	
378	        if (dotCount < 1) {
379	            return false;
380	        }
381	
382	        return !domain.startsWith(".") && !domain.endsWith(".");
383	    }
384	}
