387	import java.math.BigDecimal;
388	import java.math.RoundingMode;
389	import java.time.LocalDate;
390	import java.time.Month;
391	
392	public class PricingUtil {
393	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
394	    private static final BigDecimal DISCOUNT_PERCENTAGE = new BigDecimal("0.15");
395	
396	    public static boolean isHighSeason(LocalDate date) {
397	        Month month = date.getMonth();
398	        int dayOfMonth = date.getDayOfMonth();
399	
400	        if (month == Month.JULY) {
401	            return true;
402	        }
403	        if (month == Month.DECEMBER) {
404	            return dayOfMonth >= 15;
405	        }
406	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
407	            return true;
408	        }
409	        return false;
410	    }
411	
412	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
413	        if (isHighSeason(date)) {
414	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
415	        }
416	        return baseRate;
417	    }
418	
419	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
420	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
421	    }
422	
423	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
424	        BigDecimal total = BigDecimal.ZERO;
425	        LocalDate current = checkIn;
426	        while (current.isBefore(checkOut)) {
427	            total = total.add(calculateNightlyPrice(baseRate, current));
428	            current = current.plusDays(1);
429	        }
430	        return round(total);
431	    }
432	
433	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
434	        if ("NON_REFUNDABLE".equals(ratePlan)) {
435	            return round(subtotal.multiply(DISCOUNT_PERCENTAGE));
436	        }
437	        return BigDecimal.ZERO;
438	    }
439	
440	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
441	        return round(subtotal.subtract(discount));
442	    }
443	
444	    public static BigDecimal round(BigDecimal value) {
445	        return value.setScale(2, RoundingMode.HALF_EVEN);
446	    }
447	}
