450	import com.pousada.marealta.models.Receipt;
451	import java.math.BigDecimal;
452	import java.time.LocalDate;
453	import java.time.format.DateTimeFormatter;
454	
455	public class ReceiptFormatter {
456	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
457	    private static final DateTimeFormatter CURRENCY_FORMATTER = DateTimeFormatter.ofPattern("0.00");
458	
459	    public static String format(Receipt receipt) {
460	        StringBuilder sb = new StringBuilder();
461	        sb.append("Comprovante de reserva nº ").append(receipt.reservationId).append("\n");
462	        sb.append("Hóspede: ").append(receipt.guestName).append(" (CPF ").append(receipt.guestCpf).append(")\n");
463	        sb.append("Quarto: ").append(receipt.roomNumber).append(" (").append(receipt.roomType).append(")\n");
464	        sb.append("Entrada: ").append(formatDate(receipt.checkIn));
465	        sb.append(" | Saída: ").append(formatDate(receipt.checkOut));
466	        sb.append(" | ").append(receipt.nights).append(receipt.nights == 1 ? " diária" : " diárias").append("\n");
467	        sb.append("Diárias: ").append(formatCurrency(receipt.subtotal)).append("\n");
468	
469	        if (receipt.discount.compareTo(BigDecimal.ZERO) > 0) {
470	            sb.append("Desconto: ").append(formatCurrency(receipt.discount)).append("\n");
471	        }
472	
473	        sb.append("Total: ").append(formatCurrency(receipt.total)).append("\n");
474	
475	        return sb.toString().trim();
476	    }
477	
478	    private static String formatDate(LocalDate date) {
479	        return date.format(DATE_FORMATTER);
480	    }
481	
482	    private static String formatCurrency(BigDecimal value) {
483	        return "R$ " + value.toPlainString();
484	    }
485	}

